using namespace mxpart_mod;
using namespace sprods_com_mod;

// Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
// Eq 9.12
std::complex<double> FPFMccTtilde(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  auto zab2 = [&](int j1, int j2, int j3, int j4) {
    return za(j1, j2) * zb(j2, j4) + za(j1, j3) * zb(j3, j4);
  };
  auto zba2 = [&](int j1, int j2, int j3, int j4) {
    return zb(j1, j2) * za(j2, j4) + zb(j1, j3) * za(j3, j4);
  };
  auto zab = [&](int j1, int j2, int j3) {
    return za(j1, j2) * zb(j2, j3);
  };

  double deltat23 = s(j2, j3) - s(j5, j6) - s(j1, j4);

  std::complex<double> FPFMccTtilde;
  FPFMccTtilde =
      0.5 * (t(j1, j2, j4) * deltat23 + 2.0 * s(j1, j4) * s(j5, j6)) / std::pow(t(j1, j2, j4), 2)
      * (std::pow(zab2(j4, j1, j2, j6), 2) / (za(j1, j2) * zb(j5, j6) * zab2(j2, j1, j4, j3))
         + std::pow(zb(j1, j2) * za(j3, j5), 2) / (zb(j1, j4) * za(j5, j6) * zab2(j3, j1, j2, j4)))

      - 2.0 * zab(j4, j1, j2) * za(j2, j4) * zab(j5, j3, j6)
        / (za(j1, j2) * t(j1, j2, j4) * zab2(j2, j1, j4, j3))
      - zab(j3, j1, j2) * za(j4, j5) * zab2(j3, j1, j2, j6)
        / (za(j1, j2) * t(j1, j2, j3) * zab2(j3, j1, j2, j4))

      + 1.0 / (zab2(j2, j1, j4, j3) * zab2(j3, j1, j2, j4))
        * (zab(j4, j1, j2) * za(j2, j3) * zab(j5, j3, j6) / za(j1, j2)
           + zab(j3, j1, j2) * zab(j5, j4, j6) / (za(j1, j2) * zab2(j1, j2, j3, j4))
             * (za(j1, j2) * (s(j1, j3) - s(j2, j4)) + za(j1, j3) * zba2(j3, j1, j4, j2))

           - 0.5 * zab2(j4, j1, j2, j6) / (za(j1, j2) * zb(j5, j6))
             * (zab2(j3, j1, j2, j6) * deltat23 + 2.0 * zab(j3, j1, j6) * s(j5, j6))
           - 0.5 * zb(j1, j2) * za(j3, j5) * zab2(j5, j3, j4, j1) * deltat23
             / (zb(j1, j4) * za(j5, j6))

           + zb(j2, j6) * (zab(j4, j2, j1) * za(j3, j5) + zab(j3, j4, j1) * za(j4, j5))
           - za(j3, j4) * zb(j1, j6) * zab2(j5, j1, j3, j2));

  return FPFMccTtilde;
}

extern "C" {
  std::complex<double> FPFMccTtilde_wrapper(int j1, int j2, int j3, int j4, int j5, int j6, std::complex<double>* fza, std::complex<double>* fzb) {
    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);

    std::complex<double> FPFMccTtilde_out = FPFMccTtilde(j1, j2, j3, j4, j5, j6, za, zb);  // @coverage-probe
    return FPFMccTtilde_out;
  }
}

